/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadCaveat = makeLoadFont('Caveat');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: caveatFamily } = loadCaveat();



export type MagicCupsProps = Record<string, any>;

const HeartIcon: React.FC<{ color: string; size?: number }> = ({ color, size = 64 }) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 24 24"
    fill={color}
    xmlns="http://www.w3.org/2000/svg"
  >
    <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z" />
  </svg>
);

const MagicCups: React.FC<MagicCupsProps> = ({
  backgroundColor = "#fdf2f8",
  transparentBackground = false,
  durationInSeconds = 12,
  cupColor = "#dc2626", // Red by default for the classic American beer pong cup
  heartColor = "#ec4899",
  textColor = "#1f2937",
  introText = "Look for the heart 👀",
  lookCloselyText = "look closely~",
  questionText = "where is the heart?",
  questionTextYOffset = 0,
  leftText = "I",
  rightText = "U",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // ---------------------------------------------------------------------------
  // ELASTIC TIMING LOGIC
  // Maps base 360-frame choreography to actual duration
  // ---------------------------------------------------------------------------
  const F = useMemo(() => {
    const scale = (durationInSeconds * fps) / 360;
    return (f: number) => Math.round(f * scale);
  }, [durationInSeconds, fps]);

  // ---------------------------------------------------------------------------
  // CHOREOGRAPHY & PHYSICS STATE
  // ---------------------------------------------------------------------------
  const CUP_SPACING = 380;
  const CUP_WIDTH = 160;
  const CUP_HEIGHT = 220;

  const posToX = (posIdx: number) => (posIdx - 1) * CUP_SPACING;

  // Base keyframes mapped to actual frame timeline
  const swapConfig = useMemo(() => {
    const rawSwaps = [
      { s: 50, e: 75, p1: 0, p2: 1 },
      { s: 75, e: 95, p1: 1, p2: 2 },
      { s: 95, e: 110, p1: 0, p2: 2 },
      { s: 110, e: 120, p1: 1, p2: 2 },
      { s: 120, e: 130, p1: 0, p2: 1 },
      { s: 130, e: 145, p1: 0, p2: 2 },
      { s: 145, e: 165, p1: 1, p2: 2 },
      { s: 165, e: 190, p1: 1, p2: 2 }, // Final swap ensures Cup 0 lands at Pos 1 (Center)
    ];
    return rawSwaps.map((s) => ({ ...s, s: F(s.s), e: F(s.e) }));
  }, [F]);

  // Generate deterministic history for each cup
  const cupHistories = useMemo(() => {
    type HistEntry = { f: number; p: number; m?: boolean; t?: number; track?: number };
    const h: HistEntry[][] = [[{ f: 0, p: 0 }], [{ f: 0, p: 1 }], [{ f: 0, p: 2 }]];
    const currentPosArray = [0, 1, 2];

    swapConfig.forEach((swap) => {
      const cupA = currentPosArray.indexOf(swap.p1);
      const cupB = currentPosArray.indexOf(swap.p2);

      // Cup moving right/forward
      h[cupA].push({ f: swap.s, p: swap.p1, m: true, t: swap.p2, track: 1 });
      h[cupA].push({ f: swap.e, p: swap.p2, m: false, t: swap.p2, track: 0 });

      // Cup moving left/backward
      h[cupB].push({ f: swap.s, p: swap.p2, m: true, t: swap.p1, track: -1 });
      h[cupB].push({ f: swap.e, p: swap.p1, m: false, t: swap.p1, track: 0 });

      currentPosArray[cupA] = swap.p2;
      currentPosArray[cupB] = swap.p1;
    });

    h.forEach((hist) => hist.push({ f: 99999, p: hist[hist.length - 1].p, m: false, t: 0, track: 0 }));
    return h;
  }, [swapConfig]);

  // Evaluates cup position pure-functionally based on frame
  const getCupTransform = (cupId: number, currentFrame: number) => {
    const hist = cupHistories[cupId];
    let segIdx = 0;
    for (let i = 0; i < hist.length - 1; i++) {
      if (currentFrame >= hist[i].f && currentFrame < hist[i + 1].f) {
        segIdx = i;
        break;
      }
    }
    if (currentFrame >= hist[hist.length - 1].f) segIdx = hist.length - 1;

    const seg = hist[segIdx];
    const nextSeg = hist[segIdx + 1];
    const baseX = posToX(seg.p);

    if (seg.m && nextSeg) {
      const p = interpolate(currentFrame, [seg.f, nextSeg.f], [0, 1], {
        easing: Easing.inOut(Easing.ease),
      });
      const targetX = posToX(seg.t!);
      const x = interpolate(p, [0, 1], [baseX, targetX]);
      const y = Math.sin(p * Math.PI) * (80 * (seg.track || 0));
      return { x, y, z: (seg.track || 0) > 0 ? 10 : 5 };
    }
    return { x: baseX, y: 0, z: 5 };
  };

  // ---------------------------------------------------------------------------
  // LAYER CALCULATIONS
  // ---------------------------------------------------------------------------
  
  // Intro Lift for Cup 0 to reveal where the heart goes
  const cup0IntroLiftY = interpolate(
    frame,
    [F(10), F(20), F(35), F(45)],
    [0, -250, -250, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.inOut(Easing.ease),
    }
  );

  // End Lift mechanics for Center Reveal
  const liftSpring = spring({
    frame: frame - F(270),
    fps,
    config: { damping: 14, stiffness: 100 },
  });
  const cup0LiftY = interpolate(liftSpring, [0, 1], [0, -200]);

  // Delayed Side Lift mechanics for Left/Right Reveal
  const sideLiftsSpring = spring({
    frame: frame - F(315),
    fps,
    config: { damping: 14, stiffness: 100 },
  });
  const sideLiftY = interpolate(sideLiftsSpring, [0, 1], [0, -200]);

  // Floating small hearts
  const floatingHearts = useMemo(() => {
    return Array.from({ length: 6 }).map((_, i) => ({
      startFrame: F(290) + i * F(4),
      randScale: 0.3 + random(`scale-${i}`) * 0.4,
      randXDrift: (random(`drift-${i}`) - 0.5) * 300,
    }));
  }, [F]);

  // Main Heart Target Position
  const cup0State = getCupTransform(0, frame);
  const heartTargetX = cup0State.x;
  
  // Heart Entrance Slide (while cup is lifted)
  const heartSlideProgress = interpolate(frame, [F(15), F(30)], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });
  const heartEntranceX = interpolate(heartSlideProgress, [0, 1], [-800, heartTargetX]);
  const heartOpacity = interpolate(heartSlideProgress, [0, 0.2], [0, 1], { 
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp" 
  });
  
  const currentHeartX = frame < F(50) ? heartEntranceX : heartTargetX;
  const currentHeartY = cup0State.y; // Heart follows shuffle curves but NOT the lifts

  // Text Opacities
  const introOpacity = interpolate(frame, [F(60), F(70), F(110), F(120)], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const closelyOpacity = interpolate(frame, [F(130), F(140), F(180), F(190)], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const questionOpacity = interpolate(frame, [F(230), F(240), F(260), F(270)], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  const labelSprings = ['A', 'B', 'C'].map((_, idx) => 
    spring({ frame: frame - F(200 + idx * 5), fps, config: { damping: 12 } })
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, transition: "none" }}>
      
      {/* BACKGROUND TEXTS */}
      <AbsoluteFill style={{ alignItems: "center", top: height / 2 - 300, transition: "none" }}>
        <div style={{ fontSize: 72, fontWeight: "bold", color: textColor, opacity: introOpacity, position: "absolute", transition: "none" }}>
          {introText}
        </div>
        <div style={{ fontSize: 96, fontFamily: caveatFamily, color: textColor, opacity: closelyOpacity, position: "absolute", transition: "none" }}>
          {lookCloselyText}
        </div>
        <div style={{ 
          fontSize: 72, 
          fontWeight: "bold", 
          color: textColor, 
          opacity: questionOpacity, 
          position: "absolute", 
          transform: `translateY(${questionTextYOffset}px)`,
          transition: "none" 
        }}>
          {questionText}
        </div>
      </AbsoluteFill>

      {/* CENTERED PLAY AREA */}
      <AbsoluteFill style={{ left: width / 2, top: height / 2 + 100, overflow: "visible", transition: "none" }}>
        
        {/* UNDER CUP TEXTS (Left & Right) */}
        {[
          { text: leftText, pos: 0 },
          { text: rightText, pos: 2 }
        ].map((item) => (
          <div
            key={`under-text-${item.pos}`}
            style={{
              position: "absolute",
              left: -100,
              top: -120, // Lifted to ensure it's completely covered by the cup
              width: 200,
              height: 100,
              display: "flex",
              justifyContent: "center",
              alignItems: "center",
              transform: `translate(${posToX(item.pos)}px, 0px)`,
              opacity: interpolate(frame, [F(200), F(210)], [0, 1], { extrapolateRight: "clamp", extrapolateLeft: "clamp" }),
              fontSize: 96,
              fontWeight: "bold",
              color: textColor,
              zIndex: 1, // Behind cups
              transition: "none"
            }}
          >
            {item.text}
          </div>
        ))}

        {/* THE MAIN HEART (Starts offscreen, slides under cup 0, follows cup 0) */}
        <div style={{
            position: "absolute",
            left: -32,
            top: -64,
            transform: `translate(${currentHeartX}px, ${currentHeartY}px)`,
            opacity: heartOpacity,
            zIndex: 1, // Behind cups
            transition: "none"
        }}>
          <HeartIcon color={heartColor} size={64} />
        </div>

        {/* THE CUPS */}
        {[0, 1, 2].map((cupId) => {
          const state = getCupTransform(cupId, frame);
          // Cup 0 lifts initially and at the end. Cups 1 & 2 lift at the very end
          const liftOffset = cupId === 0 ? cup0LiftY + cup0IntroLiftY : sideLiftY;
          
          return (
            <div
              key={`cup-${cupId}`}
              style={{
                position: "absolute",
                width: CUP_WIDTH,
                height: CUP_HEIGHT,
                left: -CUP_WIDTH / 2,
                top: -CUP_HEIGHT,
                transform: `translate(${state.x}px, ${state.y + liftOffset}px)`,
                zIndex: state.z,
                transition: "none",
                // Use drop-shadow to apply shadow to the custom polygonal shape
                filter: "drop-shadow(0px 15px 15px rgba(0,0,0,0.3))",
              }}
            >
              {/* Trapazoid Body of the Beer Pong Cup (Upside Down) */}
              <div
                style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  width: "100%",
                  height: "100%",
                  clipPath: "polygon(25% 0%, 75% 0%, 92% 100%, 8% 100%)",
                  backgroundColor: cupColor,
                  // Linear gradient creates 3D cylindrical lighting effect
                  backgroundImage: "linear-gradient(90deg, rgba(0,0,0,0.3) 0%, rgba(255,255,255,0.2) 20%, rgba(255,255,255,0) 80%, rgba(0,0,0,0.3) 100%)",
                }}
              >
                {/* Horizontal Ridges typical of a solo cup */}
                {/* Top base indent */}
                <div style={{ position: "absolute", top: "0", width: "100%", height: "4%", backgroundColor: "rgba(0,0,0,0.15)" }} />
                
                {/* Grooves near the base (which is the top when upside down) */}
                <div style={{ position: "absolute", top: "8%", width: "100%", height: "2%", backgroundColor: "rgba(0,0,0,0.2)" }} />
                <div style={{ position: "absolute", top: "12%", width: "100%", height: "2%", backgroundColor: "rgba(0,0,0,0.2)" }} />
                <div style={{ position: "absolute", top: "16%", width: "100%", height: "2%", backgroundColor: "rgba(0,0,0,0.2)" }} />
                <div style={{ position: "absolute", top: "20%", width: "100%", height: "2%", backgroundColor: "rgba(0,0,0,0.2)" }} />
              </div>

              {/* The Bottom Lip (The thick rolled rim touching the table) */}
              <div
                style={{
                  position: "absolute",
                  bottom: "-6px", 
                  left: "5%", // Positioned slightly outward relative to the 8% body bottom edge
                  width: "90%",
                  height: "16px",
                  backgroundColor: cupColor,
                  borderRadius: "8px",
                  backgroundImage: "linear-gradient(90deg, rgba(0,0,0,0.3) 0%, rgba(255,255,255,0.2) 20%, rgba(255,255,255,0) 80%, rgba(0,0,0,0.3) 100%)",
                  borderBottom: "3px solid rgba(0,0,0,0.15)",
                }}
              />
            </div>
          );
        })}

        {/* LABELS A, B, C */}
        {['A', 'B', 'C'].map((label, idx) => {
          const s = labelSprings[idx];
          const yOff = interpolate(s, [0, 1], [-100, 0]);
          const opac = interpolate(s, [0, 1], [0, 1]);
          return (
            <div
              key={label}
              style={{
                position: "absolute",
                left: posToX(idx) - 30,
                top: -CUP_HEIGHT - 120,
                fontSize: 80,
                fontWeight: "bold",
                color: textColor,
                transform: `translateY(${yOff}px)`,
                opacity: opac,
                transition: "none"
              }}
            >
              {label}
            </div>
          );
        })}

        {/* FLOATING SMALL HEARTS ON REVEAL */}
        {floatingHearts.map((h, i) => {
          if (frame < h.startFrame) return null;
          const progress = interpolate(frame - h.startFrame, [0, F(60)], [0, 1], { extrapolateRight: "clamp" });
          const yOff = progress * -400;
          const xOff = progress * h.randXDrift;
          const opac = interpolate(progress, [0, 0.1, 0.8, 1], [0, 1, 1, 0]);
          const scale = h.randScale * interpolate(progress, [0, 0.1], [0, 1], { extrapolateRight: "clamp" });
          
          return (
            <div
              key={`float-${i}`}
              style={{
                position: "absolute",
                left: -32,
                top: -64,
                // Spawn at Center (Pos 1) since Cup 0 ends there
                transform: `translate(${posToX(1) + xOff}px, ${yOff}px) scale(${scale})`,
                opacity: opac,
                zIndex: 20,
                transition: "none"
              }}
            >
              <HeartIcon color={heartColor} size={64} />
            </div>
          );
        })}

      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default MagicCups;